/* 사이트에서 쓰는 이름 → Figma 컴포넌트 이름 */
const IC_ALIAS = { arrowLeft: "back", back: "chevronLeft", chevR: "chevronRight", chevron: "chevronRight", box: "drawer", flag: "report", person: "user", refresh: "reset" };
function icon(name, size = 20) {
  const s = document.createElementNS("http://www.w3.org/2000/svg", "svg");
  s.setAttribute("viewBox", "0 0 24 24"); s.setAttribute("width", size); s.setAttribute("height", size);
  s.setAttribute("class", "ic"); s.setAttribute("aria-hidden", "true");
  const path = (d, cls) => { const p = document.createElementNS(s.namespaceURI, "path"); p.setAttribute("d", d); if (cls) p.setAttribute("class", cls); return p; };
  const fk = IC_ALIAS[name] || name;
  if (IC_FIG[fk]) {   // Figma 컴포넌트 아이콘: Outlined(.ico), Filled(.icf)가 있으면 같이 넣고 상황에 따라 바꿔 보여 줌
    s.classList.add("icm", "fig");
    const grp = (list, cls) => { const g = document.createElementNS(s.namespaceURI, "g"); g.setAttribute("class", cls);
      list.forEach((x) => { if (x[0] === "@") return IC_FIG[x.slice(1)].forEach((y) => g.append(path(y.replace(/^E\|/, "")))); const p = path(x.replace(/^E\|/, "")); if (x.startsWith("E|")) p.setAttribute("fill-rule", "evenodd"); g.append(p); }); return g; };
    if (fk.endsWith(":f")) { s.classList.remove("icm"); s.classList.add("figf"); s.append(grp(IC_FIG[fk], "icx")); return s; }   // 채운 모양을 직접 요청: 상태 전환 없이 그대로
    s.append(grp(IC_FIG[fk], "ico"));
    if (IC_FIG[fk + ":f"]) s.append(grp(IC_FIG[fk + ":f"], "icf"));
    return s;
  }
  if (IC_M[name]) {   // Figma Material 아이콘: 채우기로 그림. 활성(Filled) 모양이 있으면 .icf 로 같이 넣고 상황에 따라 바꿔 보여 줌
    s.classList.add("icm");
    s.append(path(IC_M[name], "ico"));
    if (IC_M[name + ":f"]) s.append(path(IC_M[name + ":f"], "icf"));
    return s;
  }
  const p = path(IC[name]);
  if (name === "more") { p.setAttribute("fill", "currentColor"); p.setAttribute("stroke", "currentColor"); p.setAttribute("stroke-width", "1.8"); }
  s.append(p); return s;
}
function iconHTML(name, size = 20) { return icon(name, size).outerHTML; }
/* 정적 HTML 의 <i data-ic="search" data-s="20"> 자리 채우기 */
function fillIcons(root = document) { root.querySelectorAll("i[data-ic]").forEach((el) => { const s = icon(el.dataset.ic, +el.dataset.s || 20); if (el.className) el.className.split(/\s+/).forEach((c) => c && s.classList.add(c)); el.replaceWith(s); }); }

fillIcons();
